def seed_photo_requirements(apps, schema_editor):
    Site = apps.get_model("work", "Site")
    PhotoCategory = apps.get_model("work", "PhotoCategory")
    WorkSubmission = apps.get_model("work", "WorkSubmission")
    WorkPhoto = apps.get_model("work", "WorkPhoto")
    SitePhotoRequirement = apps.get_model("work", "SitePhotoRequirement")
    default_category = PhotoCategory.objects.filter(is_active=True).order_by("order", "name").first()
    if not default_category:
        return

    for site in Site.objects.all().iterator():
        latest_submission_id = WorkSubmission.objects.filter(
            plan__site_id=site.pk
        ).order_by("-created_at").values_list("pk", flat=True).first()
        category_ids = []
        if latest_submission_id:
            category_ids = list(
                WorkPhoto.objects.filter(
                    submission_id=latest_submission_id,
                    category__is_active=True,
                ).order_by("category__order", "category__name")
                .values_list("category_id", flat=True).distinct()
            )
        if not category_ids:
            category_ids = [default_category.pk]
        SitePhotoRequirement.objects.bulk_create([
            SitePhotoRequirement(site_id=site.pk, category_id=category_id, order=index)
            for index, category_id in enumerate(category_ids[:20])
        ])


